            {(task.status === 'waiting' || taskNeedsAttention(task)) && <button className="secondary" onClick={() => run(() => dllWorkspace.cancel(task.id))}>{task.status === 'waiting' ? '移除待生成' : '請求取消'}</button>}
          </div></div>)}
